-- create-table /TRBASE/AUDIT_LOG
CREATE TABLE "/TRBASE/AUDIT_LOG" (
  "/RT/TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "LOG_ID" UUID NOT NULL,
  "TEXT" TEXT COLLATE "C" NOT NULL,
  CONSTRAINT "/TRBASE/AUDIT_LOG#PK" PRIMARY KEY ("/RT/TENANT", "LOG_ID"),
  CONSTRAINT "/TRBASE/AUDIT_LOG#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /TRFIN/COUNTRIES
CREATE TABLE "/TRFIN/COUNTRIES" (
  "COUNTRY_CODE" VARCHAR(2) COLLATE "C" NOT NULL,
  "NAME" VARCHAR(80) COLLATE "C" NOT NULL,
  "CURRENCY" VARCHAR(3) COLLATE "C",
  CONSTRAINT "/TRFIN/COUNTRIES#PK" PRIMARY KEY ("COUNTRY_CODE")
);

-- create-table /TRFIN/COMPANIES
CREATE TABLE "/TRFIN/COMPANIES" (
  "/RT/TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "COMPANY_ID" VARCHAR(10) COLLATE "C" NOT NULL,
  "NAME" VARCHAR(80) COLLATE "C" NOT NULL,
  "STREET" VARCHAR(60) COLLATE "C",
  "POSTAL_CODE" VARCHAR(10) COLLATE "C",
  "CITY" VARCHAR(40) COLLATE "C",
  "COUNTRY" VARCHAR(2) COLLATE "C",
  "/TROTTO/PICKUP_POINT" VARCHAR(20) COLLATE "C",
  "STATUS" VARCHAR(10) COLLATE "C" NOT NULL DEFAULT 'ACTIVE',
  "CAPITAL" NUMERIC(15,2),
  "FOUNDED_ON" DATE,
  "CREATED_BY" VARCHAR(80) COLLATE "C",
  "CREATED_AT" TIMESTAMPTZ,
  "CHANGED_BY" VARCHAR(80) COLLATE "C",
  "CHANGED_AT" TIMESTAMPTZ,
  "/TROTTO/OTTO_ID" VARCHAR(20) COLLATE "C",
  CONSTRAINT "/TRFIN/COMPANIES#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TRFIN/COMPANIES#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/TRFIN/COMPANIES#FK#COUNTRY" FOREIGN KEY ("COUNTRY") REFERENCES "/TRFIN/COUNTRIES" ("COUNTRY_CODE") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/TRFIN/COMPANIES#CK#STATUS" CHECK ("STATUS" IN ('ACTIVE', 'BLOCKED', 'CLOSED'))
);

-- create-table /TRFIN/BANK_ACCOUNTS
CREATE TABLE "/TRFIN/BANK_ACCOUNTS" (
  "/RT/TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "COMPANY_ID" VARCHAR(10) COLLATE "C" NOT NULL,
  "ACCOUNT_NO" INTEGER NOT NULL,
  "IBAN" VARCHAR(34) COLLATE "C" NOT NULL,
  "BALANCE" NUMERIC(15,2) NOT NULL DEFAULT 0.00,
  "OPENED_AT" TIMESTAMPTZ,
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO"),
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/TRFIN/BANK_ACCOUNTS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TRFIN/COMPANIES" ("/RT/TENANT", "COMPANY_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /TRFIN/COMPANIES_ARCHIVE
CREATE TABLE "/TRFIN/COMPANIES_ARCHIVE" (
  "/RT/TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "ARCHIVE_NO" BIGINT NOT NULL,
  "ARCHIVED_AT" TIMESTAMPTZ NOT NULL,
  "COMPANY_ID" VARCHAR(10) COLLATE "C",
  "NAME" VARCHAR(80) COLLATE "C" NOT NULL,
  "STREET" VARCHAR(60) COLLATE "C",
  "POSTAL_CODE" VARCHAR(10) COLLATE "C",
  "CITY" VARCHAR(40) COLLATE "C",
  "COUNTRY" VARCHAR(2) COLLATE "C",
  "/TROTTO/PICKUP_POINT" VARCHAR(20) COLLATE "C",
  "STATUS" VARCHAR(10) COLLATE "C" NOT NULL DEFAULT 'ACTIVE',
  "CAPITAL" NUMERIC(15,2),
  "FOUNDED_ON" DATE,
  "CREATED_BY" VARCHAR(80) COLLATE "C",
  "CREATED_AT" TIMESTAMPTZ,
  "CHANGED_BY" VARCHAR(80) COLLATE "C",
  "CHANGED_AT" TIMESTAMPTZ,
  "/TROTTO/OTTO_ID" VARCHAR(20) COLLATE "C",
  CONSTRAINT "/TRFIN/COMPANIES_ARCHIVE#PK" PRIMARY KEY ("/RT/TENANT", "ARCHIVE_NO"),
  CONSTRAINT "/TRFIN/COMPANIES_ARCHIVE#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/TRFIN/COMPANIES_ARCHIVE#CK#STATUS" CHECK ("STATUS" IN ('ACTIVE', 'BLOCKED', 'CLOSED'))
);

-- create-table /TRFIN/CONTACTS
CREATE TABLE "/TRFIN/CONTACTS" (
  "/RT/TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "CONTACT_ID" UUID NOT NULL,
  "COMPANY_ID" VARCHAR(10) COLLATE "C" NOT NULL,
  "NAME" VARCHAR(80) COLLATE "C",
  "EMAIL" TEXT COLLATE "C",
  CONSTRAINT "/TRFIN/CONTACTS#PK" PRIMARY KEY ("/RT/TENANT", "CONTACT_ID"),
  CONSTRAINT "/TRFIN/CONTACTS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/TRFIN/CONTACTS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TRFIN/COMPANIES" ("/RT/TENANT", "COMPANY_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /TRFIN/EXCHANGE_RATES
CREATE TABLE "/TRFIN/EXCHANGE_RATES" (
  "FROM_CURRENCY" VARCHAR(3) COLLATE "C" NOT NULL,
  "TO_CURRENCY" VARCHAR(3) COLLATE "C" NOT NULL,
  "VALID_FROM" DATE NOT NULL,
  "RATE" NUMERIC(15,6) NOT NULL,
  CONSTRAINT "/TRFIN/EXCHANGE_RATES#PK" PRIMARY KEY ("FROM_CURRENCY", "TO_CURRENCY", "VALID_FROM")
);

-- create-table /TRFIN/ORDERS
CREATE TABLE "/TRFIN/ORDERS" (
  "/RT/TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "ORDER_ID" VARCHAR(10) COLLATE "C" NOT NULL,
  "COMPANY_ID" VARCHAR(10) COLLATE "C" NOT NULL,
  "ORDERED_ON" DATE NOT NULL,
  "AMOUNT" NUMERIC(15,2) NOT NULL,
  "NOTE" TEXT COLLATE "C",
  CONSTRAINT "/TRFIN/ORDERS#PK" PRIMARY KEY ("/RT/TENANT", "ORDER_ID"),
  CONSTRAINT "/TRFIN/ORDERS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/TRFIN/ORDERS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TRFIN/COMPANIES" ("/RT/TENANT", "COMPANY_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /TRFIN/PAYMENTS
CREATE TABLE "/TRFIN/PAYMENTS" (
  "/RT/TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "COMPANY_ID" VARCHAR(10) COLLATE "C" NOT NULL,
  "ACCOUNT_NO" INTEGER NOT NULL,
  "PAYMENT_NO" BIGINT NOT NULL,
  "AMOUNT" NUMERIC(15,2) NOT NULL,
  "CURRENCY" VARCHAR(3) COLLATE "C" NOT NULL,
  "BOOKED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/TRFIN/PAYMENTS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO", "PAYMENT_NO"),
  CONSTRAINT "/TRFIN/PAYMENTS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/TRFIN/PAYMENTS#FK#ACCOUNT" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO") REFERENCES "/TRFIN/BANK_ACCOUNTS" ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /TROTTO/OTTO_CONNECTIONS
CREATE TABLE "/TROTTO/OTTO_CONNECTIONS" (
  "/RT/TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "COMPANY_ID" VARCHAR(10) COLLATE "C" NOT NULL,
  "ENDPOINT" TEXT COLLATE "C" NOT NULL,
  "ACTIVE" BOOLEAN NOT NULL DEFAULT TRUE,
  CONSTRAINT "/TROTTO/OTTO_CONNECTIONS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TROTTO/OTTO_CONNECTIONS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/TROTTO/OTTO_CONNECTIONS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TRFIN/COMPANIES" ("/RT/TENANT", "COMPANY_ID") DEFERRABLE INITIALLY IMMEDIATE
);

